package org.eclipse.rdf4j.query.algebra.evaluation.function.string.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.IntStream;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.json.JsonSupport;
import org.eclipse.rdf4j.query.algebra.evaluation.function.support.RegexCache;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.RegexpExtractAllTupleFunction;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code strf:regexpExtract} and the scalar {@code strf:regexpExtractAll}.
 */
class RegexpExtractEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final String SMILEY = "😀";

	private static final String GRIN = "😁";

	private final RegexpExtract extract = new RegexpExtract();

	private final RegexpExtractAll extractAll = new RegexpExtractAll();

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal en(String s) {
		return VF.createLiteral(s, "en");
	}

	private static Literal integer(int i) {
		return VF.createLiteral(i);
	}

	private static List<Value> jsonArrayValues(Literal array) {
		assertThat(array.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		List<?> parsed = (List<?>) JsonSupport.parse(array.getLabel());
		List<Value> values = new ArrayList<>(parsed.size());
		for (Object element : parsed) {
			values.add(JsonSupport.toValue(element, VF));
		}
		return values;
	}

	@Test
	void noMatch() {
		// pins current behaviour: regexpExtract yields "" (same kind as the source) rather than an error
		assertThat(extract.evaluate(VF, str("xyz"), str("[0-9]+"))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, en("xyz"), str("[0-9]+"))).isEqualTo(en(""));
		assertThat(extractAll.evaluate(VF, str("xyz"), str("[0-9]+")).getLabel()).isEqualTo("[]");
		assertThat(extractAll.evaluate(VF, en("xyz"), str("[0-9]+")).getLabel()).isEqualTo("[]");
	}

	@Test
	void explicitGroupZeroIsTheWholeMatch() {
		assertThat(extract.evaluate(VF, str("abc123def"), str("([a-z]+)([0-9]+)"), integer(0)))
				.isEqualTo(str("abc123"));
		assertThat(extractAll.evaluate(VF, str("a1b2"), str("([a-z])([0-9])"), integer(0)).getLabel())
				.isEqualTo("[\"a1\",\"b2\"]");
	}

	@Test
	void namedGroupsAreAddressedByNumber() {
		Literal pattern = str("(?<key>\\w+)=(?<value>\\w+)");
		assertThat(extract.evaluate(VF, str("k=v"), pattern, integer(1))).isEqualTo(str("k"));
		assertThat(extract.evaluate(VF, str("k=v"), pattern, integer(2))).isEqualTo(str("v"));
		assertThat(extractAll.evaluate(VF, str("k=v;x=y"), pattern, integer(2)).getLabel())
				.isEqualTo("[\"v\",\"y\"]");
	}

	@Test
	void groupIndexOutOfRangeIsAnEvaluationError() {
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)"), integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)"), integer(-1)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str("(b)"), integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str("(b)"), integer(-1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void groupIndexOutOfRangeIsAnErrorEvenWithoutAMatch() {
		assertThatThrownBy(() -> extract.evaluate(VF, str("xyz"), str("(a)"), integer(5)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extractAll.evaluate(VF, str("xyz"), str("(a)"), integer(5)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new RegexpExtractAllTupleFunction().evaluate(VF, str("xyz"), str("(a)"), integer(5)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void optionalGroupThatDidNotParticipateIsEmpty() {
		// pins current behaviour: a non-participating group yields "" rather than an unbound value
		assertThat(extract.evaluate(VF, str("ac"), str("a(b)?c"), integer(1))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, str("abc"), str("a(b)?c"), integer(1))).isEqualTo(str("b"));
		assertThat(extractAll.evaluate(VF, str("ac abc ac"), str("a(b)?c"), integer(1)).getLabel())
				.isEqualTo("[\"\",\"b\",\"\"]");
	}

	@Test
	void invalidRegexIsAnEvaluationError() {
		for (String bad : List.of("(", "[a-", "a{2,1}", "*a", "(?<1>a)", "\\")) {
			assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str(bad))).as(bad)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str(bad))).as(bad)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void flags() {
		assertThat(extract.evaluate(VF, str("a\nb"), str("a.b"))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, str("a\nb"), str("a.b"), str("s"))).isEqualTo(str("a\nb"));
		assertThat(extract.evaluate(VF, str("x\nab"), str("^ab"))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, str("x\nab"), str("^ab"), str("m"))).isEqualTo(str("ab"));
		assertThat(extract.evaluate(VF, str("ab"), str("a b"))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, str("ab"), str("a b"), str("x"))).isEqualTo(str("ab"));
		assertThat(extract.evaluate(VF, str("a.b"), str("."), str("q"))).isEqualTo(str("."));
		assertThat(extract.evaluate(VF, str("a.b"), str("."))).isEqualTo(str("a"));
		assertThat(extract.evaluate(VF, str("ABC"), str("b"), str("i"))).isEqualTo(str("B"));
		assertThat(extract.evaluate(VF, str("A\nb.c"), str("a.B\\."), str("ism"))).isEqualTo(str("A\nb."));
		assertThat(extractAll.evaluate(VF, str("aAa"), str("a"), str("i")).getLabel()).isEqualTo("[\"a\",\"A\",\"a\"]");
		for (String unknown : List.of("z", "g", "iz", "I", " ")) {
			assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("b"), str(unknown))).as(unknown)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str("b"), str(unknown))).as(unknown)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void thirdArgumentIsGroupWhenIntegerAndFlagsOtherwise() {
		// pins current behaviour: the optional arguments are distinguished by datatype, not by position
		assertThat(extract.evaluate(VF, str("ABC"), str("(b)(c)"), integer(2), str("i"))).isEqualTo(str("C"));
		assertThat(extract.evaluate(VF, str("ABC"), str("(b)(c)"), str("i"), integer(2))).isEqualTo(str("C"));
		assertThat(extract.evaluate(VF, str("ABC"), str("(b)(c)"), str("i"))).isEqualTo(str("BC"));
		assertThat(extractAll.evaluate(VF, str("ABC"), str("(b)(c)"), str("i"), integer(1)).getLabel())
				.isEqualTo("[\"B\"]");
		// a group number given as a string is taken as flags, and '1' is not a flag
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)"), str("1")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void duplicateOptionalArgumentsAreAnEvaluationError() {
		// two group numbers, or two flag strings, cannot both be honoured: neither is silently dropped
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)(c)"), integer(1), integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)(c)"), str("i"), str("s")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extract.evaluate(VF, str("abc"), str("(b)(c)"), VF.createLiteral(true), str("i")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str("(b)(c)"), integer(1), integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> extractAll.evaluate(VF, str("abc"), str("(b)(c)"), str("i"), str("s")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void emptyWidthMatchesTerminate() {
		assertThat(extractAll.evaluate(VF, str("bbb"), str("a*")).getLabel()).isEqualTo("[\"\",\"\",\"\",\"\"]");
		assertThat(extractAll.evaluate(VF, str(""), str("a*")).getLabel()).isEqualTo("[\"\"]");
		assertThat(extractAll.evaluate(VF, str("aba"), str("a*")).getLabel()).isEqualTo("[\"a\",\"\",\"a\",\"\"]");
		assertThat(extractAll.evaluate(VF, str("ab"), str("")).getLabel()).isEqualTo("[\"\",\"\",\"\"]");
		assertThat(extract.evaluate(VF, str("bbb"), str("a*"))).isEqualTo(str(""));
	}

	@Test
	void unicodeClassesAndAstralInput() {
		assertThat(extract.evaluate(VF, str("héllo wörld 123"), str("\\p{L}+"))).isEqualTo(str("héllo"));
		assertThat(extractAll.evaluate(VF, str("héllo wörld 123"), str("\\p{L}+")).getLabel())
				.isEqualTo("[\"héllo\",\"wörld\"]");
		assertThat(extract.evaluate(VF, str(SMILEY), str("."))).isEqualTo(str(SMILEY));
		assertThat(extractAll.evaluate(VF, str(SMILEY + GRIN), str(".")).getLabel())
				.isEqualTo("[\"" + SMILEY + "\",\"" + GRIN + "\"]");
		assertThat(extract.evaluate(VF, str("a" + SMILEY + "b"), str("\\p{So}"))).isEqualTo(str(SMILEY));
		assertThat(extract.evaluate(VF, str("a" + SMILEY + "b"), str("a.b"))).isEqualTo(str("a" + SMILEY + "b"));
		assertThat(extract.evaluate(VF, str("a" + SMILEY + "b"), str("a..b"))).isEqualTo(str(""));
		assertThat(extract.evaluate(VF, str("ÀB"), str("àb"), str("i"))).isEqualTo(str("ÀB"));
	}

	@Test
	void languageTagOfTheSourceIsKeptInArrayElements() {
		Literal source = VF.createLiteral("a1b2", "de");
		assertThat(jsonArrayValues(extractAll.evaluate(VF, source, str("[0-9]"))))
				.containsExactly(VF.createLiteral("1", "de"), VF.createLiteral("2", "de"));
		assertThat(extract.evaluate(VF, source, str("[0-9]"))).isEqualTo(VF.createLiteral("1", "de"));
	}

	@Test
	void scalarAndMagicPropertyExtractAllAgree() {
		RegexpExtractAllTupleFunction tupleFunction = new RegexpExtractAllTupleFunction();
		List<Value[]> inputs = List.of(new Value[] { str("a1b22c333"), str("[0-9]+") },
				new Value[] { str("xyz"), str("[0-9]+") }, new Value[] { str("bbb"), str("a*") },
				new Value[] { en("k=v;x=y"), str("(\\w)=(\\w)"), integer(2) },
				new Value[] { str("ABC"), str("[a-c]"), str("i") });
		for (Value[] input : inputs) {
			List<Value> array = jsonArrayValues(extractAll.evaluate(VF, input));
			List<Value> tuples = new ArrayList<>();
			try (var rows = tupleFunction.evaluate(VF, input)) {
				while (rows.hasNext()) {
					tuples.add(rows.next().get(0));
				}
			}
			assertThat(tuples).as(input[0] + " / " + input[1]).containsExactlyElementsOf(array);
		}
	}

	@Test
	void cacheDistinguishesFlagsForTheSamePattern() {
		for (int round = 0; round < 3; round++) {
			assertThat(extract.evaluate(VF, str("A"), str("a"))).isEqualTo(str(""));
			assertThat(extract.evaluate(VF, str("A"), str("a"), str("i"))).isEqualTo(str("A"));
			assertThat(extract.evaluate(VF, str("a.b"), str("."), str("q"))).isEqualTo(str("."));
			assertThat(extract.evaluate(VF, str("a.b"), str("."))).isEqualTo(str("a"));
			assertThat(extract.evaluate(VF, str("a\nb"), str("a.b"), str("s"))).isEqualTo(str("a\nb"));
			assertThat(extract.evaluate(VF, str("a\nb"), str("a.b"), str(""))).isEqualTo(str(""));
		}
		assertThat(RegexCache.compile("a", "i").flags() & Pattern.CASE_INSENSITIVE).isNotZero();
		assertThat(RegexCache.compile("a", null).flags() & Pattern.CASE_INSENSITIVE).isZero();
		assertThat(RegexCache.compile("a", "")).isSameAs(RegexCache.compile("a", null));
	}

	@Test
	void cacheEvictionKeepsResultsCorrect() {
		String prefix = "regexpExtractEdgeCaseEviction";
		Pattern first = RegexCache.compile(prefix + "first", null);
		assertThat(RegexCache.compile(prefix + "first", null)).isSameAs(first);
		// more distinct patterns than the cache holds, so it is cleared at least once
		for (int i = 0; i < 1_500; i++) {
			String text = prefix + i;
			assertThat(extract.evaluate(VF, str("<" + text + ">"), str(Pattern.quote(text)))).isEqualTo(str(text));
		}
		// evicted entries are simply recompiled; results are unaffected
		assertThat(extract.evaluate(VF, str(prefix + "first"), str(prefix + "first"))).isEqualTo(str(prefix + "first"));
		assertThat(RegexCache.compile(prefix + "first", null).pattern()).isEqualTo(first.pattern());
		List<Boolean> concurrent = IntStream.range(0, 4_000)
				.parallel()
				.mapToObj(i -> {
					String text = prefix + (i % 200);
					return extract.evaluate(VF, str(text), str(Pattern.quote(text)), str(i % 2 == 0 ? "i" : ""))
							.getLabel()
							.equals(text);
				})
				.toList();
		assertThat(concurrent).doesNotContain(false);
	}
}
